    "section": "",
    "topic": "",
    "category": "others",
    "difficulty": "",
    "source": "",
    "solution": "if y - 1 is a factor of y3 + 4y2 + ky - 6, then\nf(1) = (1)3 + 4(1)2 + k(1) - 6 = 0 (factor theorem)\n1+4+k-6=0\n5-6+k=0\n-1 + k = 0\nk=1",
