    "subject": "mathematics",
    "year": 2014,
    "section": "",
    "topic": "",
    "category": "others",
    "difficulty": "",
    "source": "",
    "solution": "Angle of sector subtended by yam\n= 360o - (70 + 80 + 50)o\n= 360o - 200o\n= 160o\n          o\nBut   80\n      360\n            o       x T = 8000\n                        o\nT=    8000×360\n              80\n                    o\n= N36,000\n                                         o\nHence the amount spent on yam =    160\n                                   260\n                                             × N 36, 000\n\f= N16,000",
    "imageUrl": "images/math_q48.png",
    "hasPassage": false,
    "country": "NG",
    "institution": null,
    "state": null
